% ExchangeRate.m - original program as submitted in Appendix A
% (kept for reference; use ExchangeRatePredictor.m for predictions)
% Solve an Input-Output Exchange Rate prediction using Neural Network
% and Polynomial Regression
% Script generated by Neural Fitting app
% Created 09 January, 2026 19:13:16
%
% B.Sc. Computer Science project, Department of Computer Science,
% Ignatius Ajuru University of Education, Port Harcourt, Rivers State - Nigeria
% This script assumes these variables are defined:
% This section of the program trains a Neural Network on the Foreign
% currencies in relation to the Nigerian Naira
%
Currency = [128.6150 169.7328 251.9442 110.4703;118.0050 173.9755 235.1845 120.5981;139.6900 196.8683 201.1030 114.3269;150.2500 215.1252 241.1636 142.7128; 152.3000 202.0655 234.4518 152.1868;162.2000 210.4770 252.0018 159.4028;155.7500 205.8551 251.5910 156.2735;161.3500 222.9260 266.5659 151.6325; 183.4997 223.4061 285.7492 158.1794;198.9250 217.0878 294.9384 143.2634;314.9785 332.4525 388.6138 234.6163;359.9997 431.9361 486.1204 286.3192; 364.5022 417.1145 462.8465 267.3966;362.4657 406.5470 476.2999 277.5679;381.0027 468.1887 514.9142 298.0250];
Year = [2006;2007;2008;2009;2010;2011;2012;2013;2014;2015;2016;2017;2018;2019;2020];
x = Currency';
t = Year';
% Choose a Training Function
% For a list of all training functions type: help nntrain
% 'trainlm' is usually fastest.
% 'trainbr' takes longer but may be better for challenging problems.
% 'trainscg' uses less memory. Suitable in low memory situations.
trainFcn = 'trainlm'; % Levenberg-Marquardt backpropagation.
% Create a Fitting Network
hiddenLayerSize = 10;
net = fitnet(hiddenLayerSize,trainFcn);
% Setup Division of Data for Training, Validation, Testing
net.divideParam.trainRatio = 60/100;
net.divideParam.valRatio = 20/100;
net.divideParam.testRatio = 20/100;
% Train the Network
[net,tr] = train(net,x,t);
% Test the Network
y = net(x);
e = gsubtract(t,y);
performance = perform(net,t,y)
% View the Network
view(net)
% Plots
% Uncomment these lines to enable various plots.
%figure, plotperform(tr)
%figure, plottrainstate(tr)
%figure, ploterrhist(e)
%figure, plotregression(t,y)
%figure, plotfit(net,x,t)
Year1 = sim(net,[118.0050 173.9755 235.1845 120.5981]')
Year2 = sim(net,[150.2500 215.1252 241.1636 142.7128]')
% This section of the program forecasts the Naira for any year
Year = [2006 2007 2008 2009 2010 2011 2012 2013 2014 2015 2016 2017 2018 2019 2020];
USD = [128.6150 118.0050 139.6900 150.2500 152.3000 162.2000 155.7500 161.3500 183.4997 198.9250 314.9785 359.9997 364.5022 362.4657 381.0027];
EUR = [169.7328 173.9755 196.8683 215.1252 202.0655 210.4770 205.8551 222.9260 223.4061 217.0878 332.4525 431.9361 417.1145 406.5470 468.1887];
GBP = [251.9442 235.1845 201.1030 241.1636 234.4518 252.0018 251.5910 266.5659 285.7492 294.9384 388.6138 486.1204 462.8465 476.2999 514.9142];
CAD = [110.4703 120.5981 114.3269 142.7128 152.1868 159.4028 156.2735 151.6325 158.1794 143.2634 234.6163 286.3192 267.3966 277.5679 298.0250];
polyfit(Year,USD,1);
p = polyfit(Year,USD,1);
polyval(p,2021);
USD2021 = polyval(p,2021);
polyfit(Year,EUR,1);
x= polyfit(Year,EUR,1);
polyval(x,2021);
EUR2021 = polyval(x,2021);
polyfit(Year,GBP,1);
t = polyfit(Year,GBP,1);
polyval(t,2021);
GBP2021 = polyval(t,2021);
polyfit(Year,CAD,1);
z = polyfit(Year,CAD,1);
polyval(z,2021);
CAD2021 = polyval(z,2021);
plot(Year,USD,Year,EUR,Year,GBP,Year,CAD)
grid on
xlabel('Year')
ylabel('Naira')
title('Exchange Rate of Naira to USD,EUR,GBP and CAD')
legend('USD','EUR','GBP','CAD');
